fn solve(n: i8, s: Vec<char>) -> i8 {
    // Preconditions enforced by Verus specs:
    // 0 <= n, s.len() == n as usize, s only contains 'U' or 'R'
    if n == 0 {
        return 0;
    }

    // Compute positions after each move
    let mut positions: Vec<(i32, i32)> = Vec::with_capacity(n as usize);
    let mut x: i32 = 0;
    let mut y: i32 = 0;
    for i in 0..(n as usize) {
        if s[i] == 'U' {
            y += 1;
        } else if s[i] == 'R' {
            x += 1;
        }
        positions.push((x, y));
    }

    // Closure to classify position into region
    let region = |pos: (i32, i32)| -> u8 {
        if pos.0 == pos.1 {
            0u8
        } else if pos.0 > pos.1 {
            1u8
        } else {
            2u8
        }
    };

    let mut last_region: u8 = 0; // 0 means border or not set
    let mut count_transitions: i8 = 0;

    for &pos in positions.iter() {
        let r = region(pos);
        if r == 0 {
            // border, ignore
        } else {
            if last_region == 0 {
                // first time entering A or B, no transition counted
                last_region = r;
            } else if r != last_region {
                count_transitions += 1;
                last_region = r;
            }
        }
    }

    count_transitions
}